"""Original Indonesian SSW building-cleaning curriculum. No network dependency."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
modules = []

def module(id, title, description):
    modules.append(dict(id=id, title=title, description=description, lessons=[]))

def lesson(title, concept, application, steps, caution, case, response, words, phrases, checks):
    def word(s):
        jp, kana, meaning = s.split('~')
        return dict(japanese=jp, reading=kana, meaning=meaning)
    n = sum(len(m['lessons']) for m in modules) + 1
    modules[-1]['lessons'].append(dict(
        id=f'cleaning-{n:02}', title=title, minutes=25,
        objectives=[f'Menjelaskan prinsip {title.lower()}.', 'Memilih tindakan yang aman dari kasus kerja dan menjelaskan alasannya.'],
        sections=[dict(title='Prinsip dan pengetahuan kerja', body=concept), dict(title='Penerapan dan pemeriksaan hasil', body=application)],
        steps=steps.split('|'), caution=caution, scenario=case, response=response,
        vocabulary=[word(w) for w in words.split('|')], dialogue=[word(p) for p in phrases.split('|')],
        checks=[dict(prompt=q[0], options=q[1].split('|'), answer=0, explanation=q[2]) for q in checks]))

module('role', 'Dasar profesi dan mutu layanan', 'Tujuan pembersihan, lingkup kerja, etika, serta pembagian pekerjaan harian dan berkala.')
lesson('Peran petugas dan lingkup pembersihan',
       'Pembersihan gedung menjaga kebersihan, kesehatan lingkungan, keamanan, dan penampilan ruang. Bersih secara visual belum tentu memenuhi persyaratan higienis. Lingkup pekerjaan ditentukan kontrak dan instruksi kerja: area, permukaan, jadwal, metode, serta standar hasil. Petugas tidak mengambil tugas teknis lain hanya karena terlihat mudah. Perbaikan listrik, pengendalian bahan berbahaya, dan pekerjaan di ketinggian memerlukan kewenangan serta pelatihan tersendiri.',
       'Sebelum mulai, baca daftar ruang dan batas pekerjaan. Cocokkan kebutuhan pengguna dengan jadwal gedung, lalu tanyakan bagian yang belum jelas. Perhatikan penghuni, barang pribadi, dan jalur evakuasi. Setelah selesai, bandingkan hasil dengan standar: debu dan noda terangkat, permukaan aman, perlengkapan lengkap, serta tidak ada kerusakan baru. Laporkan hambatan dengan lokasi dan fakta agar pekerjaan berikutnya dapat direncanakan.',
       'Baca lingkup kerja|Periksa kondisi awal|Pilih metode yang diizinkan|Periksa dan laporkan hasil', 'Jangan membuka panel atau membongkar instalasi tanpa kewenangan.',
       'Kamu diminta membuka panel listrik yang berdebu.', 'Jelaskan batas tugas dan laporkan kepada penanggung jawab teknis.',
       '清掃~せいそう~pembersihan|建物~たてもの~gedung|作業~さぎょう~pekerjaan|範囲~はんい~lingkup',
       '作業範囲を確認します。~さぎょうはんいをかくにんします。~Saya akan memeriksa lingkup pekerjaan.|責任者に報告します。~せきにんしゃにほうこくします。~Saya akan melapor kepada penanggung jawab.',
       [('Panel listrik kotor di luar lingkup tugas. Apa tindakan tepat?', 'Laporkan ke penanggung jawab teknis|Buka panel sendiri|Semprot dengan air|Abaikan tanpa laporan', 'Batas tugas dan risiko listrik harus diperiksa sebelum pekerjaan dilakukan.'), ('Standar hasil kerja sebaiknya ditentukan dari apa?', 'Instruksi kerja dan kebutuhan permukaan|Kecepatan saja|Bau pewangi saja|Jumlah air yang dipakai', 'Standar meliputi kebersihan, keamanan, kondisi permukaan, serta kontrak pekerjaan.')])
lesson('Pembersihan harian, berkala, dan inspeksi',
       'Pembersihan harian menangani kotoran yang muncul dari penggunaan rutin, misalnya debu, sampah, dan bekas sentuhan. Pembersihan berkala menangani akumulasi atau pemeliharaan yang tidak perlu dilakukan setiap hari, seperti pencucian mesin lantai atau perawatan lapisan pelindung. Inspeksi bukan sekadar tanda tangan: kondisi awal dan hasil akhir harus diperiksa berdasarkan daftar area. Frekuensi disesuaikan penggunaan dan spesifikasi gedung.',
       'Susun urutan agar area yang sudah bersih tidak terkotori kembali. Tentukan waktu untuk pekerjaan yang membutuhkan pengeringan atau pembatasan akses. Jika pekerjaan berkala tidak dapat dilakukan karena ruangan masih dipakai, catat pekerjaan yang tertunda dan koordinasikan waktu pengganti. Jangan mengganti metode berkala dengan proses cepat yang merusak bahan. Gunakan catatan inspeksi untuk menemukan noda berulang dan penyebabnya.',
       'Baca jadwal|Pisahkan pekerjaan harian dan berkala|Koordinasikan akses|Catat hasil inspeksi', 'Jangan menandai pekerjaan selesai jika area belum diperiksa.',
       'Jadwal pencucian lantai bertabrakan dengan rapat.', 'Koordinasikan penjadwalan ulang dan catat area yang belum dikerjakan.',
       '日常清掃~にちじょうせいそう~pembersihan harian|定期清掃~ていきせいそう~pembersihan berkala|点検~てんけん~pemeriksaan|予定~よてい~jadwal',
       '予定を変更できますか。~よていをへんこうできますか。~Apakah jadwal dapat diubah?|まだ終わっていません。~まだおわっていません。~Belum selesai.',
       [('Pencucian berkala tidak dapat dilakukan saat ruang dipakai. Apa yang dilakukan?', 'Koordinasikan dan catat penundaan|Centang selesai|Paksakan saat rapat|Hilangkan dari jadwal', 'Catatan penundaan menjaga keterlacakan dan keselamatan pengguna.'), ('Pembersihan harian terutama menangani apa?', 'Kotoran dari penggunaan rutin|Perbaikan panel listrik|Penggantian struktur lantai|Semua pelapisan setiap hari', 'Pekerjaan harian berbeda dari pemeliharaan berkala dan perbaikan teknis.')])
lesson('Etika, privasi, dan pelayanan pengguna',
       'Petugas bekerja di ruang yang dapat berisi dokumen, perangkat, dan barang pribadi. Jangan membaca, memotret, atau memindahkan isinya di luar kebutuhan yang diizinkan. Barang temuan diserahkan melalui prosedur gedung dengan pencatatan lokasi dan waktu. Sikap sopan mencakup memberi salam, meminta izin masuk, membatasi kebisingan, dan menghormati penggunaan ruangan. Identitas pemilik tidak boleh diumumkan sembarangan.',
       'Ketuk atau sampaikan maksud sebelum masuk area yang sedang digunakan. Tanyakan kepada atasan jika dokumen menghalangi pembersihan, alih-alih menganggap semua benda di meja adalah sampah. Jika pengguna menyampaikan keluhan, dengarkan dan ulangi inti masalah, lalu laporkan secara faktual. Jangan berjanji melakukan pekerjaan di luar kontrak. Gunakan saluran resmi untuk barang hilang dan informasi penghuni.',
       'Minta izin|Jaga dokumen dan barang|Catat barang temuan|Serahkan melalui prosedur', 'Jangan mengambil foto dokumen untuk laporan kebersihan.',
       'Ada dompet di bawah kursi ruang rapat.', 'Catat lokasi dan serahkan kepada petugas yang ditunjuk tanpa memeriksa isi untuk kepentingan pribadi.',
       '忘れ物~わすれもの~barang tertinggal|貴重品~きちょうひん~barang berharga|許可~きょか~izin|利用者~りようしゃ~pengguna',
       '清掃に入ってもよろしいですか。~せいそうにはいってもよろしいですか。~Bolehkah saya masuk untuk membersihkan?|忘れ物がありました。~わすれものがありました。~Ada barang tertinggal.',
       [('Kertas di meja menghalangi pembersihan. Pilih tindakan tepat.', 'Tanyakan prosedur sebelum memindahkan|Buang semua kertas|Foto isinya|Baca untuk menentukan pemilik', 'Dokumen bukan sampah hanya karena berada di area kerja.'), ('Dompet temuan harus bagaimana?', 'Diserahkan melalui prosedur barang temuan|Dibawa pulang|Diumumkan isinya|Ditaruh di tong sampah', 'Pencatatan dan penyerahan resmi melindungi pemilik serta petugas.')])

module('safety', 'Keselamatan dan kesehatan kerja', 'Penilaian bahaya, pembatasan area, APD, ergonomi, dan respons insiden.')
lesson('Bahaya terpeleset dan pembatasan area',
       'Air, kabel, alat, dan perbedaan permukaan dapat menyebabkan jatuh. Rambu memperingatkan, sedangkan pembatas membantu mengendalikan akses; keduanya dipilih sesuai risiko dan aturan lokasi. Rambu ditempatkan sebelum pekerjaan basah dimulai, terlihat dari jalur datang pengguna. Jangan menutup seluruh jalur tanpa koordinasi. Pengeringan dan pemeriksaan akhir menentukan kapan area boleh dibuka, bukan semata waktu yang sudah berlalu.',
       'Periksa jalur alternatif, pintu darurat, dan pengguna yang membutuhkan bantuan mobilitas. Kerjakan lantai dalam zona kecil sehingga akses aman tetap tersedia. Jika ada tumpahan di luar area kerja, amankan atau minta bantuan segera. Rambu baru dipindahkan setelah lantai kering, alat tersimpan, dan tidak ada sisa licin. Bila tidak bisa mengendalikan arus orang, hentikan pekerjaan dan koordinasikan waktu lain.',
       'Periksa arus pengguna|Pasang rambu dan pembatas|Kerjakan per zona|Buka setelah kering dan aman', 'Rambu saja tidak menghilangkan risiko lantai licin.',
       'Lantai lobi basah dan pengunjung terus lewat.', 'Batasi zona basah, sediakan jalur aman, dan koordinasikan bantuan.',
       '滑る~すべる~terpeleset|危険~きけん~bahaya|表示~ひょうじ~tanda|通路~つうろ~jalur lewat',
       '床が滑りやすいです。~ゆかがすべりやすいです。~Lantainya mudah membuat terpeleset.|こちらをお通りください。~こちらをおとおりください。~Silakan lewat sini.',
       [('Kapan rambu lantai basah boleh dipindahkan?', 'Setelah kering dan area diperiksa aman|Begitu mengepel selesai|Saat atasan pergi|Setelah lima menit tanpa pemeriksaan', 'Pembukaan area berdasarkan kondisi nyata, bukan waktu perkiraan saja.'), ('Jalur evakuasi harus bagaimana saat pembersihan?', 'Tetap aman dan tidak terhalang|Dipakai menyimpan troli|Ditutup tanpa koordinasi|Diisi ember', 'Jalur evakuasi tidak boleh dihalangi oleh alat atau pembatas.')])
lesson('APD, postur, dan pengangkatan beban',
       'Alat pelindung diri dipilih dari risiko pekerjaan dan label bahan: sarung tangan yang sesuai, sepatu tidak licin, serta pelindung mata bila ada risiko percikan. Sarung tangan tidak menggantikan kebersihan tangan. Membungkuk terus-menerus, memutar badan sambil mengangkat, dan membawa ember terlalu penuh meningkatkan cedera. Gunakan alat dengan panjang sesuai tubuh, bagi beban, dan gunakan troli bila tersedia.',
       'Periksa APD sebelum dipakai dan ganti yang robek atau terkontaminasi. Saat memindahkan beban, nilai berat dan jalurnya dahulu. Dekatkan beban ke tubuh dan hindari memutar pinggang; pindahkan kaki untuk berganti arah. Jangan memaksakan beban yang tidak dapat dikendalikan. Minta bantuan sesuai prosedur. Sesuaikan tinggi gagang dan selingi aktivitas untuk mengurangi gerakan berulang.',
       'Nilai risiko dan berat|Pakai APD sesuai label|Gunakan troli atau bantuan|Periksa kelelahan dan kondisi alat', 'Jangan mengangkat beban yang tidak diketahui beratnya sendirian.',
       'Kantong sampah basah terasa sangat berat.', 'Jangan dipaksakan; amankan, gunakan alat bantu dan minta bantuan sesuai prosedur.',
       '手袋~てぶくろ~sarung tangan|保護具~ほごぐ~alat pelindung|姿勢~しせい~postur|台車~だいしゃ~troli',
       '手伝ってください。~てつだってください。~Tolong bantu saya.|台車を使います。~だいしゃをつかいます。~Saya akan menggunakan troli.',
       [('Sarung tangan robek saat kerja. Apa yang tepat?', 'Hentikan dan ganti secara aman|Lanjutkan hingga istirahat|Tutup dengan kertas|Gunakan sisi yang robek', 'APD rusak tidak memberikan perlindungan yang direncanakan.'), ('Cara mengurangi risiko saat beban terlalu berat?', 'Gunakan alat bantu dan bantuan|Memutar pinggang lebih cepat|Menjauhkan beban dari tubuh|Mengangkat sambil berlari', 'Alat bantu dan pembagian beban lebih aman daripada memaksakan postur.')])
lesson('Insiden, bahan tumpah, dan keadaan darurat',
       'Utamakan keselamatan diri dan orang di sekitar ketika terjadi insiden. Kenali cara menghubungi penanggung jawab dan nomor darurat lokasi sebelum mulai bekerja. Tumpahan tidak dikenal diperlakukan sebagai potensi bahaya; jangan menyentuh, menghirup, atau mencampurkan bahan lain. Kebakaran, cedera, atau paparan bahan ditangani mengikuti prosedur darurat dan informasi SDS. Petugas tidak boleh memasuki area berbahaya tanpa pelatihan serta perlindungan.',
       'Hentikan aktivitas, batasi akses dari posisi aman, lalu laporkan lokasi, jenis kejadian, dan orang yang terdampak. Bila darurat, aktifkan respons darurat gedung tanpa menunda untuk menyelesaikan tugas. Pertolongan dilakukan sesuai pelatihan dan petunjuk petugas darurat. Simpan informasi produk untuk membantu penanganan. Catat kejadian dan nyaris celaka setelah situasi aman, termasuk tindakan yang sudah diambil.',
       'Jauhkan diri dari bahaya|Amankan akses dari tempat aman|Panggil bantuan|Laporkan fakta setelah aman', 'Jangan menetralkan tumpahan yang tidak dikenal dengan bahan lain.',
       'Botol tanpa label pecah dan mengeluarkan bau menyengat.', 'Jauhi area, cegah orang mendekat dari posisi aman, dan hubungi penanggung jawab darurat.',
       '事故~じこ~kecelakaan|避難~ひなん~evakuasi|救急~きゅうきゅう~pertolongan darurat|漏れ~もれ~kebocoran',
       'ここに近づかないでください。~ここにちかづかないでください。~Jangan mendekati tempat ini.|すぐに連絡してください。~すぐにれんらくしてください。~Tolong segera hubungi petugas.',
       [('Bahan tanpa label tumpah. Tindakan awal?', 'Jauhi, batasi akses, dan laporkan|Cium untuk mengenali|Campur dengan pemutih|Lap dengan tangan kosong', 'Bahan tak dikenal tidak boleh diuji sendiri atau dicampur.'), ('Apa isi laporan insiden yang berguna?', 'Lokasi, waktu, kondisi, dan tindakan|Dugaan tanpa fakta|Kesalahan rekan saja|Foto pribadi pengguna', 'Laporan faktual membantu respons dan pencegahan kejadian berulang.')])

module('chemicals', 'Kotoran, bahan permukaan, dan bahan kimia', 'Pemilihan metode menurut kotoran, label, SDS, pengenceran, serta kompatibilitas material.')
lesson('Mengenali kotoran dan bahan permukaan',
       'Debu lepas, minyak, kerak mineral, dan noda terserap membutuhkan pendekatan berbeda. Mulai dari metode paling ringan yang efektif dan sesuai permukaan. Batu alam, kayu, logam, kaca, lapisan lantai, serta tekstil memiliki ketahanan berbeda terhadap air, gesekan, asam, dan alkali. Noda yang tampak serupa belum tentu sama; periksa spesifikasi material sebelum memilih bahan dan alat.',
       'Angkat kotoran lepas terlebih dahulu agar tidak menggores ketika digosok. Jika material belum diketahui, tanyakan dan uji di area tersembunyi sesuai izin. Jangan langsung memakai bahan kuat. Perhatikan perubahan warna, kilap, atau tekstur selama uji. Jika tanda kerusakan muncul, hentikan dan laporkan. Catat metode yang berhasil untuk penggunaan berikutnya dalam instruksi lokasi.',
       'Identifikasi material|Kenali jenis kotoran|Pilih metode ringan dan uji|Periksa perubahan permukaan', 'Asam dapat merusak batu tertentu; jangan menebak kompatibilitas.',
       'Ada kerak di lantai batu yang jenisnya belum diketahui.', 'Periksa spesifikasi material sebelum menggunakan pembersih kerak.',
       '汚れ~よごれ~kotoran|材質~ざいしつ~bahan material|油~あぶら~minyak|傷~きず~goresan',
       '材質を確認してください。~ざいしつをかくにんしてください。~Tolong periksa jenis bahannya.|目立たない所で試します。~めだたないところでためします。~Saya akan menguji di tempat tersembunyi.',
       [('Material lantai belum diketahui. Pilihan aman?', 'Periksa spesifikasi sebelum bahan kuat|Langsung pakai asam|Gosok dengan logam|Rendam semalaman', 'Kompatibilitas bergantung pada material, bukan hanya jenis noda.'), ('Mengapa debu dan pasir diangkat sebelum menggosok?', 'Mengurangi risiko goresan|Menambah kilap kimia|Mengganti disinfeksi|Menghilangkan kebutuhan rambu', 'Partikel kasar dapat menggores ketika tertarik alat pembersih.')])
lesson('Label, SDS, dan penyimpanan bahan',
       'Label produk menjelaskan penggunaan, bahaya, pengenceran, serta perlindungan yang dibutuhkan. SDS menyediakan informasi keselamatan seperti bahaya, penanganan, pertolongan pertama, dan penyimpanan. Jangan memakai bahan dari wadah tanpa identitas. Pemindahan ke botol kerja hanya melalui prosedur berlabel yang diizinkan. Bahan yang tidak kompatibel disimpan terpisah; tutup rapat dan cegah akses pengguna gedung.',
       'Cocokkan produk dengan tugas, lalu baca label sebelum membuka. Pastikan lokasi SDS diketahui dan dapat diakses. Gunakan wadah yang sesuai serta label yang terbaca; botol minuman tidak boleh dijadikan wadah bahan kimia. Simpan dalam tempat yang ditentukan, tidak di jalur evakuasi atau dekat makanan. Jika label hilang, pisahkan dengan aman dan tanyakan penanggung jawab, jangan mencoba mengidentifikasi lewat bau.',
       'Baca label|Temukan SDS|Periksa wadah dan identitas|Simpan sesuai kompatibilitas', 'Jangan mencampur produk; pemutih berklorin dengan asam dapat melepaskan gas berbahaya.',
       'Rekan memberikan botol minuman berisi cairan pembersih.', 'Jangan gunakan; ikuti prosedur identifikasi dan penyimpanan berlabel.',
       '洗剤~せんざい~deterjen|表示~ひょうじ~label|保管~ほかん~penyimpanan|混ぜる~まぜる~mencampur',
       '混ぜないでください。~まぜないでください。~Jangan dicampur.|ラベルがありません。~らべるがありません。~Labelnya tidak ada.',
       [('Wadah bahan kimia yang benar?', 'Wadah sesuai prosedur dengan label jelas|Botol minuman tanpa label|Gelas kantin|Botol acak berdasarkan warna', 'Identitas dan wadah sesuai mencegah paparan serta salah penggunaan.'), ('Pemutih berklorin boleh dicampur pembersih asam?', 'Tidak, dapat menghasilkan gas berbahaya|Ya agar lebih kuat|Ya dengan air panas|Ya bila baunya enak', 'Campuran kimia yang tidak kompatibel berbahaya; ikuti label produk.')])
lesson('Pengenceran dan waktu kontak',
       'Larutan terlalu pekat dapat meninggalkan residu, merusak bahan, atau meningkatkan paparan; terlalu encer dapat gagal mencapai hasil. Baca definisi rasio: pengenceran 100 kali berarti volume produk merupakan seper seratus volume akhir, jika demikian tertulis pada petunjuk. Ini berbeda dari notasi 1:100 produk terhadap air. Gunakan satuan dan alat ukur yang benar. Waktu kontak disinfektan mengikuti produk; tidak ada angka universal untuk semua bahan.',
       'Hitung kebutuhan akhir agar tidak menyiapkan berlebihan. Untuk 1 liter larutan dengan pengenceran akhir 100 kali, dibutuhkan 10 ml produk dan air hingga volume akhir 1000 ml, bukan 1000 ml air ditambah produk. Jika label memakai definisi lain, ikuti definisinya. Campurkan hanya sesuai urutan dan kondisi yang disyaratkan label. Jangan menambah bahan untuk mempercepat kerja. Tandai identitas larutan dan batas pakainya sesuai prosedur.',
       'Baca definisi rasio pada label|Hitung volume akhir|Ukur dengan alat sesuai|Ikuti waktu kontak dan penanganan residu', 'Jangan gunakan botol tak berlabel atau menebak konsentrasi dari warna.',
       'Label meminta pengenceran akhir 100 kali untuk 1 liter.', 'Ukur 10 ml konsentrat dan tambahkan air sampai volume total 1000 ml sesuai petunjuk produk.',
       '希釈~きしゃく~pengenceran|濃度~のうど~konsentrasi|計量~けいりょう~pengukuran|時間~じかん~waktu',
       '濃度を確認します。~のうどをかくにんします。~Saya akan memeriksa konsentrasi.|説明書どおりに使います。~せつめいしょどおりにつかいます。~Saya akan menggunakan sesuai petunjuk.',
       [('Pengenceran AKHIR 100 kali, volume akhir 1000 ml. Berapa produk?', '10 ml|100 ml|1 ml|1000 ml', '1000 dibagi 100 = 10 ml produk; tambahkan air hingga volume akhir.'), ('Waktu kontak disinfektan ditentukan oleh apa?', 'Petunjuk produk dan penggunaan|Angka yang sama untuk semua produk|Bau larutan|Keinginan bekerja cepat', 'Konsentrasi, permukaan, dan waktu kontak harus mengikuti petunjuk produk.')])

module('tools', 'Peralatan manual dan mesin', 'Kain, mop, vacuum, mesin lantai, inspeksi listrik, dan penyimpanan alat.')
lesson('Kain lap, mop, dan pemisahan alat',
       'Kain dan mop yang kotor dapat memindahkan kotoran antar-area. Sistem pemisahan alat berdasarkan zona membantu mencegah kontaminasi silang; warna spesifik ditentukan lokasi, bukan aturan universal. Lipat kain untuk menyediakan beberapa sisi bersih. Ganti sisi ketika kotor, lalu ganti kain sesuai prosedur. Alat toilet tidak digunakan pada meja atau area bersih. Kain lembap berbeda dari kain yang menetes.',
       'Siapkan jumlah kain cukup dan pisahkan wadah bersih dari bekas pakai. Gunakan metode lap searah atau tumpang tindih yang teratur agar area tidak terlewat. Jangan mencelupkan alat kotor ke larutan bersih bila prosedur melarangnya. Setelah tugas, cuci atau proses alat sesuai spesifikasi, keringkan, dan simpan bersih. Kain yang lembap disimpan tertutup tanpa pengeringan dapat menjadi sumber bau dan pencemaran.',
       'Pisahkan alat per zona|Lipat dan gunakan sisi bersih|Ganti alat yang kotor|Cuci dan keringkan setelah kerja', 'Kode warna mengikuti aturan gedung; jangan menganggap satu warna berlaku di semua tempat.',
       'Kain dari toilet hendak dipakai untuk meja resepsionis.', 'Hentikan dan gunakan kain khusus area meja yang bersih.',
       '雑巾~ぞうきん~kain lap|モップ~もっぷ~mop|交換~こうかん~penggantian|乾燥~かんそう~pengeringan',
       '新しい布に替えます。~あたらしいぬのにかえます。~Saya mengganti dengan kain bersih.|道具を分けて使います。~どうぐをわけてつかいます。~Saya memakai alat yang dipisahkan.',
       [('Kain toilet boleh digunakan ke meja?', 'Tidak, gunakan alat zona meja|Boleh bila tampak bersih|Boleh setelah disemprot pewangi|Boleh bila warna sama', 'Pemisahan alat mencegah kontaminasi silang antar-zona.'), ('Setelah dicuci, kain sebaiknya bagaimana?', 'Dikeringkan dan disimpan bersih|Dibiarkan basah dalam kantong|Ditaruh di lantai|Dicampur sampah', 'Pengeringan dan penyimpanan membantu menjaga kondisi higienis alat.')])
lesson('Vacuum cleaner dan pengendalian debu',
       'Vacuum mengangkat debu melalui aliran udara dan penyaringan. Jenis kering tidak otomatis aman untuk cairan. Gunakan mesin yang dirancang untuk tugas dan bahan yang akan diangkat. Kantong atau wadah penuh dan filter tersumbat menurunkan hisap. Debu berbahaya atau bahan tak dikenal tidak ditangani dengan vacuum biasa. Pilih nozzle sesuai permukaan dan periksa roda agar tidak menggores lantai.',
       'Sebelum memasang steker, periksa kabel, bodi, filter, dan kapasitas wadah. Rencanakan jalur kabel jauh dari arus pengguna serta genangan. Angkat benda besar secara aman terlebih dahulu. Gerakkan nozzle teratur, tidak terlalu cepat, dan tumpang tindih. Jika hisap turun, matikan dan cabut sebelum pemeriksaan sesuai manual. Buang debu menurut prosedur tanpa menghamburkannya kembali.',
       'Periksa jenis mesin dan kabel|Atur jalur kerja|Vacuum sistematis|Matikan dan rawat sesuai manual', 'Jangan mengisap air dengan vacuum yang hanya untuk debu kering.',
       'Ada genangan di dekat vacuum kering.', 'Hentikan dan pilih peralatan penanganan cairan yang diizinkan.',
       '掃除機~そうじき~vacuum cleaner|吸引~きゅういん~pengisapan|電源~でんげん~daya listrik|ほこり~ほこり~debu',
       '電源を切ります。~でんげんをきります。~Saya mematikan listrik.|吸い込みが弱いです。~すいこみがよわいです。~Daya isapnya lemah.',
       [('Vacuum kering boleh mengisap genangan?', 'Tidak, gunakan alat yang sesuai cairan|Boleh semua vacuum|Boleh jika cepat|Boleh tanpa filter', 'Desain mesin menentukan apakah cairan aman diisap.'), ('Sebelum membuka bagian untuk membersihkan sumbatan?', 'Matikan dan putus daya sesuai manual|Biarkan menyala|Tarik selang sambil berjalan|Tambah air', 'Isolasi daya diperlukan untuk pemeriksaan dan perawatan aman.')])
lesson('Mesin lantai dan keselamatan listrik',
       'Mesin lantai memerlukan latihan langsung dan izin penggunaan. Pad, sikat, kecepatan, larutan, serta jenis lantai harus cocok; warna pad tidak cukup untuk menentukan kompatibilitas. Periksa kabel, steker, kebocoran, serta pengaman. Tangan basah dan air di dekat sambungan listrik meningkatkan bahaya. Kabel rusak tidak diperbaiki sementara oleh operator tanpa kewenangan. Mesin bergerak tidak boleh ditinggalkan tanpa kendali.',
       'Baca manual, inspeksi area, dan siapkan pembatas sebelum pemasangan. Pasang aksesori saat daya terputus sesuai petunjuk. Atur gagang agar terkendali dan kelola kabel tanpa melewati zona basah. Jangan menjalankan mesin di tangga atau bidang yang tidak diizinkan. Jika muncul suara, getaran, bau, atau percikan tidak normal, hentikan, isolasi sesuai prosedur, dan beri label alat tidak boleh dipakai.',
       'Periksa izin dan kondisi|Pasang aksesori saat daya terputus|Operasikan dalam zona aman|Hentikan bila ada kelainan', 'Materi ini tidak menggantikan pelatihan langsung mengendalikan mesin.',
       'Kabel mesin terkelupas namun motor masih bekerja.', 'Jangan gunakan; isolasi alat dan laporkan untuk pemeriksaan teknis.',
       '機械~きかい~mesin|故障~こしょう~kerusakan|点検~てんけん~inspeksi|使用禁止~しようきんし~dilarang digunakan',
       'この機械は使えません。~このきかいはつかえません。~Mesin ini tidak dapat digunakan.|異常があります。~いじょうがあります。~Ada kondisi tidak normal.',
       [('Kabel terkelupas tetapi mesin berfungsi. Apa yang tepat?', 'Hentikan, tandai, dan laporkan|Tetap gunakan|Balut tisu|Pegang bagian terkelupas', 'Fungsi motor tidak membuktikan keamanan kabel listrik.'), ('Aksesori mesin dipilih berdasarkan apa?', 'Manual, jenis permukaan, dan tugas|Warna favorit|Harga saja|Ukuran sepatu operator', 'Kompatibilitas pad/sikat dan material menentukan metode yang aman.')])

module('floors', 'Lantai keras dan karpet', 'Pengangkatan debu, pengepelan, pencucian, pelindung lantai, dan tekstil.')
lesson('Mengangkat debu dan mengepel lantai keras',
       'Pasir dan debu lepas diangkat sebelum pengepelan agar tidak menjadi lumpur atau menggores. Pilih dust mop atau vacuum sesuai material dan kondisi. Pengepelan memakai kadar kelembapan yang sesuai; banyak air tidak selalu lebih bersih. Kayu, sambungan, dan beberapa lantai berlapis peka terhadap kelembapan berlebih. Bekerjalah teratur dengan jalur keluar agar tidak menginjak area yang sudah dibersihkan.',
       'Siapkan rambu, periksa kotoran tajam, dan angkat debu dari tepi ke area yang dapat dikumpulkan. Gunakan larutan sesuai label dan mop yang tidak menetes. Bagi zona, ganti larutan yang kotor, dan periksa sisa residu. Area harus cukup kering sebelum dibuka. Bila ditemukan bagian lantai terangkat, retak, atau licin setelah kering, laporkan dan tandai agar pengguna tidak tersandung.',
       'Amankan zona|Angkat debu lepas|Pel dengan kelembapan sesuai|Periksa kering dan bebas residu', 'Jangan membanjiri lantai yang material atau sambungannya peka air.',
       'Lantai tetap lengket setelah dipel dengan larutan pekat.', 'Batasi area dan tangani residu sesuai prosedur produk; koreksi pengenceran.',
       '床~ゆか~lantai|水拭き~みずぶき~mengelap lembap|乾拭き~からぶき~mengelap kering|砂~すな~pasir',
       '先にほこりを取ります。~さきにほこりをとります。~Saya mengangkat debu terlebih dahulu.|床が乾くまでお待ちください。~ゆかがかわくまでおまちください。~Tunggu sampai lantai kering.',
       [('Urutan pembersihan lantai yang tepat?', 'Angkat debu lalu pel sesuai material|Pel di atas pasir|Tuang konsentrat dahulu|Buka rambu sebelum mulai', 'Pengangkatan partikel mengurangi lumpur dan goresan.'), ('Air berlebih pada lantai peka air dapat apa?', 'Merusak material atau sambungan|Selalu mempercepat pengeringan|Mengganti deterjen|Menghilangkan semua risiko', 'Volume air disesuaikan material dan metode, bukan sebanyak mungkin.')])
lesson('Pencucian dan lapisan pelindung lantai',
       'Pencucian berkala mengangkat kotoran yang tidak teratasi pembersihan harian. Lapisan pelindung hanya diterapkan pada lantai yang sesuai spesifikasi. Pengupasan lapisan lama adalah pekerjaan berbeda dan dapat melibatkan bahan lebih berisiko. Jangan menganggap semua lantai membutuhkan wax. Sisa larutan, permukaan lembap, serta debu yang tertinggal dapat mengganggu daya lekat dan penampilan lapisan.',
       'Konfirmasi spesifikasi lantai dan rencana perawatan kepada atasan. Siapkan area dengan waktu pengeringan memadai, pembatas, ventilasi sesuai label, serta alat terpisah untuk aplikasi lapisan. Kerjakan tahap pencucian, penanganan residu, pengeringan, dan aplikasi sesuai sistem produk. Jangan menambah lapisan berikutnya sebelum syarat pengeringan terpenuhi. Periksa hasil dalam pencahayaan cukup sebelum area dikembalikan.',
       'Konfirmasi sistem perawatan|Cuci dan tangani residu|Pastikan kondisi kering sesuai produk|Aplikasikan dan inspeksi sesuai prosedur', 'Pengupasan dan pelapisan memerlukan supervisi serta instruksi produk, bukan percobaan sendiri.',
       'Atasan meminta pelapis tetapi lantai masih lembap.', 'Tunda aplikasi sampai syarat permukaan dan pengeringan terpenuhi.',
       '洗浄~せんじょう~pencucian|樹脂~じゅし~resin|塗布~とふ~aplikasi lapisan|剥離~はくり~pengupasan',
       'まだ乾いていません。~まだかわいていません。~Belum kering.|仕様を確認します。~しようをかくにんします。~Saya memeriksa spesifikasi.',
       [('Semua lantai harus diberi wax?', 'Tidak, ikuti spesifikasi material|Ya setiap hari|Ya termasuk semua karpet|Ya tanpa pemeriksaan', 'Lapisan pelindung harus cocok dengan sistem lantai.'), ('Sebelum aplikasi lapisan, apa yang penting?', 'Kebersihan dan kondisi kering sesuai produk|Debu dibiarkan|Air menggenang|Larutan sengaja dipekatkan', 'Residu dan kelembapan dapat mengganggu hasil serta keselamatan.')])
lesson('Karpet, noda, dan pengeringan tekstil',
       'Karpet membutuhkan pengangkatan debu teratur, terutama jalur padat pengguna. Noda ditangani segera dengan metode yang sesuai serat, pewarna, dan lapisan bawah. Menekan atau menyerap tumpahan berbeda dari menggosok kuat; gosokan dapat menyebarkan noda dan merusak serat. Uji bahan di area tersembunyi. Mesin ekstraksi dan volume cairan harus sesuai spesifikasi agar karpet tidak terlalu basah.',
       'Identifikasi bahan serta sumber noda bila diketahui tanpa menyentuh bahan berbahaya. Angkat bagian padat dengan aman lalu serap cairan menggunakan kain bersih, bekerja dari tepi menuju tengah. Jangan menggunakan beberapa produk sekaligus. Sesudah perawatan, pastikan pengeringan dan ventilasi yang diizinkan; area lembap tetap dibatasi. Noda lama atau tidak dikenal yang sulit hilang perlu dilaporkan, bukan digosok tanpa batas.',
       'Periksa material dan noda|Serap dari tepi ke tengah|Gunakan metode yang disetujui|Batasi area sampai cukup kering', 'Jangan membasahi berlebihan atau mencampur penghilang noda.',
       'Kopi baru tumpah di karpet ruang tunggu.', 'Amankan area, serap dengan kain bersih dan tangani sesuai prosedur material.',
       '繊維~せんい~serat|染み~しみ~noda|吸収~きゅうしゅう~penyerapan|換気~かんき~ventilasi',
       'こすらずに吸い取ります。~こすらずにすいとります。~Serap tanpa menggosok.|乾燥中です。~かんそうちゅうです。~Sedang dikeringkan.',
       [('Tumpahan cairan biasa pada karpet sebaiknya bagaimana?', 'Serap sesuai prosedur dari tepi ke tengah|Gosok keras ke luar|Banjiri air panas|Campur semua penghilang noda', 'Penyerapan terarah membantu mencegah noda meluas dan serat rusak.'), ('Karpet lembap setelah perawatan boleh langsung dibuka?', 'Belum, pastikan kondisi aman dan kering sesuai prosedur|Ya selalu|Ya jika wangi|Ya jika rambu mahal', 'Kelembapan dan keselamatan area harus diperiksa sebelum akses dibuka.')])

module('sanitary', 'Toilet dan area sanitasi', 'Urutan zona, wastafel, kloset, pencegahan kontaminasi, dan pengisian perlengkapan.')
lesson('Persiapan dan alur pembersihan toilet',
       'Toilet memiliki risiko kontaminasi yang berbeda dari ruang kantor. Pastikan izin masuk dan privasi pengguna sebelum menutup zona. Gunakan APD dan alat khusus sesuai sistem gedung. Prinsip umum adalah bergerak dari area lebih bersih ke lebih kotor dan dari atas ke bawah, sambil mengikuti prosedur spesifik fasilitas. Alat kloset tidak dipindahkan ke wastafel atau pegangan pintu.',
       'Pasang tanda pekerjaan dan pastikan ruang kosong sesuai prosedur. Periksa benda tajam, kebocoran, serta fasilitas rusak tanpa memasukkan tangan ke tempat yang tidak terlihat. Angkat sampah dan bersihkan zona dengan alat terpisah. Ganti kain dan sarung tangan bila diperlukan sebelum berpindah ke area bersih. Setelah selesai, periksa lantai kering, perlengkapan cukup, dan sanitasi alat sebelum disimpan.',
       'Konfirmasi ruang kosong dan pasang tanda|Siapkan APD dan alat zona|Kerjakan dari lebih bersih ke kotor|Periksa dan pulihkan akses', 'Jika ada jarum atau darah, ikuti protokol khusus; jangan anggap sampah biasa.',
       'Toilet masih dipakai ketika jadwal pembersihan tiba.', 'Hormati privasi dan koordinasikan akses aman sebelum masuk.',
       '便所~べんじょ~toilet|清潔~せいけつ~bersih higienis|汚染~おせん~kontaminasi|立入禁止~たちいりきんし~dilarang masuk',
       '清掃中です。~せいそうちゅうです。~Sedang dibersihkan.|別のトイレをご利用ください。~べつのといれをごりようください。~Silakan gunakan toilet lain.',
       [('Alat kloset dipakai ke wastafel. Apa masalahnya?', 'Memindahkan kontaminasi ke area lebih bersih|Mempercepat disinfeksi|Menghemat dengan aman|Tidak ada bila basah', 'Alat harus dipisah menurut zona dan jenis tugas.'), ('Sebelum masuk toilet untuk membersihkan?', 'Pastikan akses dan privasi sesuai prosedur|Langsung masuk semua bilik|Foto pengguna|Matikan semua lampu', 'Keselamatan dan privasi pengguna diperiksa sebelum pekerjaan.')])
lesson('Wastafel, kloset, dan titik sentuh',
       'Wastafel, kloset, tombol flush, pegangan pintu, dan keran membutuhkan alat serta urutan berbeda. Kotoran harus dibersihkan sebelum tahap disinfeksi bila disyaratkan prosedur. Pembersihan mengangkat kotoran; disinfeksi menggunakan produk dengan kondisi penggunaan tertentu. Menyemprot pewangi bukan pengganti keduanya. Hindari percikan dan jangan menyemprot ke perangkat listrik atau sensor yang tidak tahan cairan.',
       'Gunakan produk sesuai material dan label, dengan kontak serta pembilasan bila diwajibkan. Lap titik sentuh memakai sisi kain bersih. Ikuti prosedur kloset dengan sikat khusus, cegah aerosol dan percikan sebanyak mungkin, dan jangan mencampur pembersih. Periksa kebocoran atau flush tidak berfungsi lalu laporkan. Lantai di sekitar fasilitas harus kering dan bebas residu licin sebelum toilet dibuka kembali.',
       'Bersihkan kotoran|Gunakan produk sesuai label|Pisahkan alat dan titik sentuh|Periksa fungsi dan kekeringan', 'Bahan klorin dan asam tidak boleh dicampur, termasuk sisa produk pada permukaan.',
       'Rekan hendak menambah pemutih pada kloset yang baru diberi pembersih asam.', 'Hentikan dan ikuti instruksi keselamatan serta penanganan produk; jangan campurkan.',
       '洗面台~せんめんだい~wastafel|便器~べんき~kloset|蛇口~じゃぐち~keran|接触~せっしょく~sentuhan',
       '洗剤を混ぜないでください。~せんざいをまぜないでください。~Jangan campurkan deterjen.|水漏れがあります。~みずもれがあります。~Ada kebocoran air.',
       [('Pewangi dapat menggantikan pembersihan?', 'Tidak, bau tidak membuktikan kebersihan|Ya jika kuat|Ya pada semua toilet|Ya tanpa pemeriksaan', 'Kotoran dan kondisi higienis harus ditangani dengan metode yang tepat.'), ('Titik sentuh dibersihkan memakai apa?', 'Kain bersih sesuai zona dan produk tepat|Sikat kloset|Kain lantai bekas|Tangan kosong saja', 'Pemisahan alat mencegah perpindahan kontaminasi ke titik sentuh.')])
lesson('Perlengkapan toilet dan pemeriksaan akhir',
       'Pengisian sabun, kertas, dan perlengkapan adalah bagian mutu layanan. Gunakan produk yang ditentukan dan jaga kemasan dari kontaminasi. Dispenser tidak selalu boleh diisi ulang di atas sisa lama; ikuti sistem kartrid atau prosedur pembersihan yang ditetapkan. Jangan mencampurkan produk berbeda. Pemeriksaan akhir mencakup kebersihan, kelengkapan, fungsi, kekeringan lantai, dan barang yang tertinggal.',
       'Periksa persediaan sebelum bekerja agar area tidak dibiarkan tertutup lama. Simpan stok di tempat kering, bersih, dan tidak menghalangi jalan. Jika dispenser rusak, laporkan dan gunakan solusi sementara hanya jika diizinkan. Catat kekurangan stok serta fasilitas yang memerlukan perbaikan. Lepas pembatas setelah memastikan toilet siap dipakai dan tidak ada alat yang tertinggal di bilik.',
       'Periksa stok|Isi dengan sistem yang ditentukan|Periksa fungsi dan lantai|Catat kekurangan dan buka akses', 'Jangan mencampur sabun atau mengisi ulang tanpa mengikuti prosedur dispenser.',
       'Sabun tersisa sedikit tetapi produk pengganti berbeda jenis.', 'Jangan mencampur; konfirmasikan sistem penggantian yang disetujui.',
       '補充~ほじゅう~pengisian ulang|石けん~せっけん~sabun|在庫~ざいこ~stok|不足~ふそく~kekurangan',
       '石けんを補充します。~せっけんをほじゅうします。~Saya akan mengisi sabun.|在庫が足りません。~ざいこがたりません。~Stok tidak cukup.',
       [('Sabun berbeda jenis boleh langsung dicampur?', 'Tidak, ikuti prosedur penggantian|Ya agar penuh|Ya jika warnanya sama|Ya tanpa label', 'Campuran dan pengisian yang salah dapat menyebabkan kontaminasi atau gangguan produk.'), ('Apa yang diperiksa sebelum membuka toilet?', 'Fungsi, kebersihan, stok, dan lantai aman|Bau saja|Jam saja|Warna seragam', 'Pemeriksaan menyeluruh memastikan fasilitas benar-benar siap digunakan.')])

module('glass', 'Kaca, logam, dan area umum', 'Kaca terjangkau, stainless steel, tangga, lift, dan area ramai.')
lesson('Kaca dan teknik squeegee',
       'Pembersihan kaca dimulai dengan pemeriksaan retak, lapisan khusus, dan kondisi bingkai. Gunakan produk yang sesuai serta alat yang tidak menggores. Squeegee menarik larutan dari permukaan; karet rusak atau kotor dapat meninggalkan garis. Pekerjaan dalam materi ini dibatasi pada area yang dapat dijangkau dengan aman dari lantai. Pekerjaan fasad, tali, dan ketinggian memerlukan pelatihan serta prosedur khusus.',
       'Lindungi lantai dan area sekitar dari tetesan. Angkat debu yang dapat menggores, basahi sesuai kebutuhan, dan tarik squeegee dengan lintasan tumpang tindih. Bersihkan tepi karet dengan kain sesuai prosedur. Periksa hasil dari sudut berbeda, keringkan bingkai dan genangan. Jangan berdiri di kursi atau menjulurkan tubuh keluar jendela. Jika area tidak terjangkau, laporkan untuk metode akses yang diizinkan.',
       'Periksa kaca dan akses|Lindungi area bawah|Bersihkan dengan alat sesuai|Periksa garis dan keringkan tepi', 'Kursi bukan alat akses kerja di ketinggian.',
       'Bagian atas kaca tidak terjangkau dari lantai.', 'Jangan menaiki kursi; gunakan metode akses yang disetujui dan operator terlatih.',
       '窓~まど~jendela|ガラス~がらす~kaca|枠~わく~bingkai|水滴~すいてき~tetes air',
       'ガラスにひびがあります。~がらすにひびがあります。~Ada retak pada kaca.|高い所は担当者に確認します。~たかいところはたんとうしゃにかくにんします。~Saya akan mengonfirmasi pekerjaan tinggi kepada petugas.',
       [('Kaca tidak terjangkau. Apa yang tepat?', 'Gunakan metode akses resmi dan petugas terlatih|Naik kursi beroda|Berdiri di ember|Menjulur keluar jendela', 'Risiko jatuh tidak diselesaikan dengan alat improvisasi.'), ('Squeegee meninggalkan garis. Periksa apa?', 'Kondisi karet dan kebersihannya|Volume pewangi|Warna dinding|Jam gedung', 'Karet kotor atau rusak mengganggu pengangkatan larutan dari kaca.')])
lesson('Stainless steel dan permukaan sensitif',
       'Logam yang tampak sama dapat memiliki lapisan dan arah finishing berbeda. Stainless steel tidak berarti kebal terhadap semua bahan kimia atau goresan. Gunakan kain lembut dan produk yang diizinkan, sering kali mengikuti arah serat finishing. Hindari abrasif atau bahan kuat tanpa spesifikasi. Pada perangkat elektronik dan panel lift, cairan tidak boleh masuk sambungan, tombol, atau celah.',
       'Identifikasi bahan serta petunjuk produsen sebelum membersihkan. Gunakan cairan secukupnya pada kain bila prosedur mengizinkan, bukan menyemprot langsung ke panel. Angkat sidik jari tanpa menggosok berlebihan. Keringkan sesuai instruksi untuk mengurangi bekas air, kemudian periksa noda dan perubahan permukaan. Laporkan karat, korosi, atau kerusakan lapisan; jangan mencoba menutupinya dengan pelapis sembarangan.',
       'Periksa finishing|Pilih kain dan produk sesuai|Lap terarah tanpa membanjiri|Keringkan dan periksa', 'Jangan semprot langsung panel listrik atau tombol lift.',
       'Sidik jari ada pada panel tombol lift.', 'Gunakan metode kain yang sesuai instruksi perangkat dan cegah cairan masuk.',
       '金属~きんぞく~logam|表面~ひょうめん~permukaan|指紋~しもん~sidik jari|錆~さび~karat',
       '直接スプレーしないでください。~ちょくせつすぷれーしないでください。~Jangan semprot langsung.|柔らかい布を使います。~やわらかいぬのをつかいます。~Saya menggunakan kain lembut.',
       [('Cara membersihkan panel tombol elektronik?', 'Metode kain sesuai manual tanpa cairan masuk|Semprot sampai menetes|Rendam panel|Gosok logam kasar', 'Celah perangkat harus dilindungi dari cairan.'), ('Stainless steel tahan semua bahan kimia?', 'Tidak, tetap perlu kompatibilitas|Ya tanpa batas|Ya bila panas|Ya bila digosok kuat', 'Lapisan dan finishing dapat rusak oleh produk atau gesekan yang salah.')])
lesson('Tangga, lift, dan jalur ramai',
       'Pembersihan area sirkulasi harus mengendalikan benturan, jatuh, dan akses darurat. Tangga memiliki tepi, sudut, serta pegangan yang perlu diperiksa. Jangan meletakkan ember atau kabel di anak tangga. Pekerjaan lift perlu koordinasi agar pintu dan kabin tidak bergerak secara tak terduga saat metode tertentu dilakukan. Eskalator dan mesin bergerak ditangani hanya sesuai isolasi serta pelatihan yang diwajibkan.',
       'Rencanakan pekerjaan pada waktu yang sesuai kepadatan pengguna. Bagi zona dan arahkan orang melalui jalur aman; jangan meninggalkan alat tanpa pengawasan. Gunakan metode terkontrol pada tangga agar tidak kehilangan keseimbangan. Bersihkan pegangan dengan alat zona yang sesuai. Jika ada ubin lepas, tepi rusak, atau pintu lift bermasalah, tandai dan laporkan. Jangan melakukan perbaikan mekanis sendiri.',
       'Koordinasikan arus orang|Amankan zona tanpa menutup evakuasi|Kerjakan dengan posisi stabil|Periksa dan laporkan kerusakan', 'Jangan menyentuh mekanisme lift atau eskalator yang sedang bergerak.',
       'Kabel vacuum harus melintasi pintu keluar darurat.', 'Ubah rute atau metode kerja dan koordinasikan agar jalur tetap aman.',
       '階段~かいだん~tangga|手すり~てすり~pegangan|出口~でぐち~pintu keluar|段差~だんさ~beda tinggi',
       '通路をふさがないでください。~つうろをふさがないでください。~Jangan menghalangi jalur.|足元にご注意ください。~あしもとにごちゅういください。~Harap perhatikan pijakan.',
       [('Tempat menyimpan ember saat membersihkan tangga?', 'Area aman yang tidak menghalangi jalan|Di tengah anak tangga|Di pintu darurat|Di tepi anak tangga', 'Alat tidak boleh menciptakan bahaya tersandung atau menutup akses.'), ('Kerusakan tepi tangga ditemukan. Apa tindakan tepat?', 'Tandai bahaya dan laporkan|Tutup dengan kain lepas|Abaikan|Perbaiki struktur sendiri', 'Penandaan dan laporan memungkinkan penanganan teknis yang sesuai.')])

module('waste', 'Sampah dan pencegahan kontaminasi', 'Pemilahan, benda tajam, kebersihan tangan, dan perbedaan membersihkan dengan disinfeksi.')
lesson('Pemilahan dan pengangkutan sampah',
       'Kategori sampah mengikuti aturan pemerintah daerah dan gedung. Jangan menganggap semua plastik atau semua kertas memiliki jalur pembuangan sama. Pisahkan bahan yang ditetapkan, lindungi data rahasia melalui prosedur khusus, dan jangan mengorek isi kantong dengan tangan. Kantong yang terlalu penuh atau bocor meningkatkan paparan serta beban. Gunakan troli dan rute pengangkutan yang tidak mencemari area bersih.',
       'Periksa kondisi tempat sampah dan adanya benda tajam secara visual. Tutup kantong sesuai prosedur, jangan menekan isinya dengan tangan atau tubuh. Jika bocor, gunakan penanganan tambahan sesuai ketentuan tanpa menyentuh isinya langsung. Bersihkan tempat sampah dengan alat khusus dan pasang pelapis yang benar. Bawa ke titik pengumpulan yang ditentukan, jaga akses dan kebersihan jalur, lalu bersihkan tangan setelah melepas APD.',
       'Kenali kategori lokal|Tutup tanpa memadatkan dengan tangan|Angkut melalui rute aman|Bersihkan alat dan tangan', 'Baterai, bahan kimia, dan dokumen rahasia memerlukan jalur khusus sesuai aturan.',
       'Kantong penuh berisi benda yang tidak terlihat.', 'Jangan ditekan; tutup dan tangani sesuai batas kapasitas serta risiko.',
       'ごみ~ごみ~sampah|分別~ぶんべつ~pemilahan|回収~かいしゅう~pengumpulan|袋~ふくろ~kantong',
       'ごみを分別してください。~ごみをぶんべつしてください。~Tolong pilah sampah.|袋が破れています。~ふくろがやぶれています。~Kantongnya robek.',
       [('Bolehkah menekan sampah dalam kantong dengan tangan?', 'Tidak, ada risiko benda tajam tersembunyi|Ya jika pakai sarung tipis|Ya agar hemat|Ya jika kantong hitam', 'Sarung tangan tidak menghilangkan risiko tusukan dari isi tak terlihat.'), ('Aturan pemilahan sampah mengacu pada apa?', 'Ketentuan daerah dan gedung|Warna favorit|Satu aturan untuk semua negara|Kecepatan angkut saja', 'Kategori dan jalur pembuangan bergantung ketentuan lokasi.')])
lesson('Benda tajam dan cairan tubuh',
       'Jarum, kaca pecah, darah, dan cairan tubuh tidak diperlakukan sebagai sampah atau tumpahan biasa. Hindari menyentuh langsung dan jauhkan orang dari area. Penanganan memerlukan petugas terlatih, perlindungan, alat, serta wadah yang tepat. Sarung tangan biasa tidak membuat tangan tahan tusukan. Jangan mengambil jarum, memasang ulang tutupnya, atau memasukkannya ke kantong sampah umum.',
       'Laporkan temuan dengan lokasi tepat dan tunggu bantuan sesuai protokol fasilitas. Jika tugas penanganan bukan kewenanganmu, jangan memulai. Setelah paparan atau cedera, ikuti prosedur pertolongan dan penilaian medis segera; jangan menunggu akhir shift. Informasikan jenis paparan tanpa menyebarkan identitas pengguna. Pembersihan dan disinfeksi area mengikuti protokol khusus serta instruksi produk oleh personel yang berwenang.',
       'Hindari kontak|Batasi area|Hubungi petugas terlatih|Ikuti pelaporan paparan bila terjadi', 'Jangan mengambil jarum dengan tangan atau memasang kembali tutupnya.',
       'Jarum bekas ditemukan di toilet umum.', 'Amankan lokasi dan hubungi petugas sesuai protokol benda tajam.',
       '針~はり~jarum|血液~けつえき~darah|破片~はへん~pecahan|感染~かんせん~infeksi',
       '針が落ちています。~はりがおちています。~Ada jarum terjatuh.|触らないでください。~さわらないでください。~Jangan disentuh.',
       [('Jarum bekas ditemukan. Apa yang tepat?', 'Amankan area dan hubungi petugas sesuai protokol|Ambil dengan tangan|Tutup kembali jarumnya|Masukkan ke sampah kertas', 'Penanganan benda tajam memerlukan alat, wadah, dan pelatihan khusus.'), ('Terkena tusukan saat kerja. Apa yang dilakukan?', 'Segera ikuti prosedur paparan dan penilaian medis|Tunggu akhir bulan|Rahasiakan tanpa tindakan|Lanjutkan kerja saja', 'Penanganan paparan perlu cepat sesuai protokol fasilitas.')])
lesson('Kebersihan tangan dan disinfeksi yang tepat',
       'Kebersihan tangan memutus perpindahan kotoran dan mikroorganisme. Bersihkan tangan pada saat yang ditetapkan, termasuk setelah melepas sarung tangan dan setelah tugas kotor. Jika tangan terlihat kotor, gunakan pencucian dengan sabun dan air sesuai pedoman fasilitas. Disinfeksi permukaan dilakukan bila ditetapkan berdasarkan risiko, bukan sebagai pengganti pembersihan. Produk dipilih untuk permukaan serta sasaran penggunaan yang sesuai.',
       'Siapkan alat bersih dan alur yang tidak mempertemukan kain bekas dengan persediaan bersih. Bersihkan kotoran sebelum disinfeksi sesuai petunjuk, gunakan konsentrasi serta waktu kontak yang benar, dan tangani residu bila diwajibkan. Jangan menyemprot disinfektan ke orang atau mengaburkan ruangan tanpa prosedur khusus. Periksa titik sentuh serta kondisi alat, lalu dokumentasikan pekerjaan sesuai daftar fasilitas.',
       'Jaga alur bersih dan kotor|Bersihkan kotoran|Disinfeksi bila diperlukan sesuai label|Bersihkan tangan setelah tugas', 'Sarung tangan dan bau disinfektan bukan bukti permukaan sudah aman.',
       'Sarung tangan dilepas setelah membersihkan toilet.', 'Lakukan kebersihan tangan sesuai prosedur sebelum memegang alat atau barang bersih.',
       '手洗い~てあらい~cuci tangan|消毒~しょうどく~disinfeksi|清拭~せいしき~pengelapan|衛生~えいせい~higiene',
       '手を洗います。~てをあらいます。~Saya mencuci tangan.|清掃してから消毒します。~せいそうしてからしょうどくします。~Saya membersihkan sebelum disinfeksi.',
       [('Setelah melepas sarung tangan dari tugas kotor?', 'Lakukan kebersihan tangan|Langsung pegang makanan|Cukup ganti seragam|Semprot pewangi', 'Tangan dapat terkontaminasi selama pelepasan sarung tangan.'), ('Disinfeksi menggantikan pengangkatan kotoran?', 'Tidak, ikuti tahap pembersihan dan label|Ya selalu|Ya jika cairan banyak|Ya tanpa waktu kontak', 'Kotoran dapat mengganggu efektivitas proses disinfeksi.')])

module('planning', 'Perencanaan, komunikasi, dan mutu', 'Urutan kerja, laporan, pemeriksaan hasil, efisiensi air, dan keluhan.')
lesson('Membaca instruksi dan merencanakan urutan',
       'Instruksi kerja menjelaskan lokasi, target, alat, larutan, waktu, serta pemeriksaan. Konfirmasikan istilah, angka, dan satuan yang belum dipahami. Prioritas adalah keselamatan dan persyaratan layanan, bukan bergerak secepat mungkin. Urutan dari atas ke bawah dan dari lebih bersih ke lebih kotor membantu mengurangi pengulangan, tetapi selalu disesuaikan rencana lokasi dan risiko pengguna.',
       'Baca rencana sebelum menyiapkan troli, lalu cocokkan alat dan stok. Perhitungkan waktu pengeringan, pergantian pengguna, serta titik pembuangan. Jika instruksi bertentangan dengan label atau kondisi aktual, hentikan dan tanyakan. Gunakan konfirmasi ulang dengan kata sendiri agar angka pengenceran dan ruang tujuan tidak tertukar. Jangan mengisi catatan selesai untuk pekerjaan yang belum dilakukan.',
       'Baca instruksi lengkap|Ulangi bagian penting|Siapkan alat dan rute|Konfirmasi perubahan kondisi', 'Jangan menebak angka atau instruksi Jepang yang belum dipahami.',
       'Instruksi pengenceran terdengar berbeda dari label.', 'Hentikan persiapan dan konfirmasikan kepada penanggung jawab dengan menunjukkan label.',
       '指示~しじ~instruksi|手順~てじゅん~urutan kerja|確認~かくにん~konfirmasi|準備~じゅんび~persiapan',
       'もう一度説明してください。~もういちどせつめいしてください。~Tolong jelaskan sekali lagi.|この手順でよろしいですか。~このてじゅんでよろしいですか。~Apakah urutan ini benar?',
       [('Instruksi tidak jelas. Apa yang tepat?', 'Tanyakan dan konfirmasi ulang|Tebak agar cepat|Lewati keselamatan|Pakai konsentrasi tertinggi', 'Konfirmasi mencegah kesalahan metode, angka, dan lokasi.'), ('Prinsip umum urutan pembersihan?', 'Atas ke bawah sesuai rencana dan risiko|Kotor ke bersih selalu|Acak tanpa inspeksi|Lantai dahulu lalu debu plafon', 'Urutan terencana mengurangi pengotoran kembali area yang sudah bersih.')])
lesson('Inspeksi mutu, kerusakan, dan keluhan',
       'Mutu dinilai dari hasil yang dapat diperiksa: tidak ada debu atau noda sesuai standar, permukaan aman, tidak ada residu mengganggu, dan perlengkapan siap. Bandingkan kondisi sebelum serta setelah kerja untuk menemukan kerusakan. Keluhan pengguna adalah informasi yang perlu dicatat secara netral. Jangan menghapus bukti atau menyalahkan orang tanpa fakta; sampaikan kondisi dan tindakan yang dapat diverifikasi.',
       'Gunakan daftar periksa area, perhatikan sudut serta titik sentuh yang mudah terlewat. Jika standar belum tercapai, perbaiki dengan metode yang diizinkan atau laporkan keterbatasannya. Catat kerusakan dengan lokasi serta waktu melalui saluran resmi, tanpa memotret data pribadi. Dengarkan keluhan sampai selesai, konfirmasikan inti masalah, dan sampaikan kepada penanggung jawab agar tindak lanjut tidak hilang.',
       'Bandingkan hasil dengan standar|Periksa area terlewat|Catat kerusakan faktual|Laporkan dan ikuti tindak lanjut', 'Jangan menutupi kerusakan atau menjanjikan perbaikan di luar kewenangan.',
       'Pengguna mengeluh lantai masih lengket setelah dibersihkan.', 'Amankan risiko, periksa residu dan laporkan untuk koreksi sesuai prosedur.',
       '品質~ひんしつ~mutu|報告~ほうこく~laporan|破損~はそん~kerusakan|苦情~くじょう~keluhan',
       '確認して報告します。~かくにんしてほうこくします。~Saya akan memeriksa dan melapor.|どこに問題がありますか。~どこにもんだいがありますか。~Di mana letak masalahnya?',
       [('Kerusakan ditemukan setelah kerja. Apa tindakan tepat?', 'Catat fakta dan laporkan|Sembunyikan dengan troli|Salahkan pengguna|Abaikan agar cepat', 'Pelaporan faktual memungkinkan penilaian dan penanganan yang tepat.'), ('Keluhan pengguna ditanggapi dengan apa?', 'Dengarkan, konfirmasi, dan tindak lanjuti|Berdebat tanpa memeriksa|Janji apa pun|Membagikan identitasnya', 'Komunikasi netral membantu penyelesaian tanpa janji di luar kewenangan.')])
lesson('Penggunaan sumber daya dan serah terima shift',
       'Efisiensi berarti mencapai standar dengan bahan, air, energi, dan waktu yang sesuai, tanpa mengurangi keselamatan. Pengenceran benar mengurangi pemborosan serta residu. Pemeliharaan alat membantu kinerja dan umur pakai. Serah terima shift memuat pekerjaan selesai, tertunda, area masih dibatasi, kerusakan, serta kebutuhan stok. Informasi yang tidak disampaikan dapat membuat rekan membuka area yang belum aman.',
       'Hitung kebutuhan larutan, hindari air mengalir tanpa tujuan, dan matikan mesin setelah selesai sesuai manual. Bersihkan serta keringkan alat sebelum penyimpanan. Kembalikan bahan ke lokasi resmi dan periksa troli tidak meninggalkan bahaya. Tulis serah terima singkat dengan lokasi dan status jelas, termasuk siapa yang telah dihubungi. Rekan penerima perlu memahami area yang belum boleh dibuka.',
       'Siapkan volume sesuai kebutuhan|Rawat dan simpan alat|Catat tugas tertunda dan bahaya|Konfirmasikan serah terima', 'Hemat bahan tidak berarti mengencerkan di luar petunjuk atau melewati waktu kontak.',
       'Shift selesai tetapi karpet masih basah dan dibatasi.', 'Sampaikan lokasi, status pengeringan, dan kewajiban pemeriksaan sebelum membuka area.',
       '引継ぎ~ひきつぎ~serah terima|節水~せっすい~hemat air|節電~せつでん~hemat listrik|未完了~みかんりょう~belum selesai',
       'この場所はまだ使えません。~このばしょはまだつかえません。~Area ini belum dapat digunakan.|次の担当者に伝えます。~つぎのたんとうしゃにつたえます。~Saya menyampaikan kepada petugas berikutnya.',
       [('Karpet masih basah saat pergantian shift. Apa yang perlu disampaikan?', 'Lokasi, status, dan pemeriksaan sebelum membuka|Hanya salam|Nilai ujian|Warna seragam', 'Serah terima menjaga bahaya tidak terlewat saat pergantian petugas.'), ('Cara menghemat bahan dengan aman?', 'Siapkan volume dan pengenceran sesuai label|Encerkan sesuka hati|Lewati waktu kontak|Campur sisa semua produk', 'Efisiensi tidak boleh mengubah syarat efektivitas dan keselamatan.')])

module('japanese', 'Bahasa Jepang kerja dan integrasi kasus', 'Rambu, angka, percakapan, pembacaan jadwal, dan keputusan terpadu.')
lesson('Rambu dan instruksi keselamatan Jepang',
       'Rambu dan kata larangan sering memakai bentuk singkat. 立入禁止 berarti dilarang masuk, 使用禁止 berarti dilarang menggunakan, 清掃中 berarti sedang dibersihkan, dan 注意 berarti perhatikan atau hati-hati. Jangan hanya mengenali warna rambu; baca kata serta lokasi penerapannya. Jika tidak memahami instruksi, hentikan tindakan yang berisiko dan tanyakan. Kata kerja negatif seperti 触らないでください meminta agar tidak menyentuh.',
       'Latih membaca rambu dengan menghubungkan artinya ke tindakan: menjauh dari area terlarang, memilih alat lain ketika alat diberi tanda rusak, atau memakai jalur alternatif. Jangan memindahkan tanda agar pekerjaan lebih cepat. Pada percakapan, ulangi informasi penting untuk memastikan pemahaman, misalnya lokasi dan area yang ditutup. Rambu tetap dipasang sampai syarat pembukaan area benar-benar terpenuhi.',
       'Baca kata rambu|Hubungkan dengan lokasi dan tindakan|Tanyakan jika ragu|Patuhi sampai dinyatakan aman', 'Memahami satu kata tidak cukup jika angka, lokasi, atau larangannya belum jelas.',
       'Mesin bertanda 使用禁止 tersedia di gudang.', 'Jangan gunakan dan tanyakan status alat kepada penanggung jawab.',
       '禁止~きんし~larangan|注意~ちゅうい~perhatian|清掃中~せいそうちゅう~sedang dibersihkan|故障中~こしょうちゅう~sedang rusak',
       '使用禁止です。~しようきんしです。~Dilarang digunakan.|ここは立入禁止です。~ここはたちいりきんしです。~Dilarang masuk ke sini.',
       [('使用禁止 berarti apa?', 'Dilarang digunakan|Silakan digunakan|Sudah kering|Stok tersedia', '使用 berarti penggunaan dan 禁止 berarti larangan.'), ('清掃中 pada pintu menunjukkan apa?', 'Sedang dibersihkan; ikuti pembatasan|Toko tutup selamanya|Perbaikan listrik selesai|Bebas masuk semua orang', '清掃中 menunjukkan proses pembersihan sedang berlangsung.')])
lesson('Jadwal, satuan, dan laporan singkat',
       'Instruksi kerja sering menggabungkan waktu, lantai gedung, volume, dan lokasi. 午前 berarti sebelum tengah hari, 午後 setelah tengah hari, 階 menunjukkan lantai, dan 毫升 biasanya ditulis ml pada produk. Angka tanpa satuan dapat menimbulkan salah tafsir. Baca jadwal secara utuh: kegiatan apa, di mana, kapan, dan syarat selesai. Untuk laporan, pisahkan fakta kejadian dari dugaan penyebab.',
       'Gunakan pola lokasi + kondisi + tindakan: 三階のトイレで水漏れがあります, ada kebocoran di toilet lantai tiga. Konfirmasikan angka dengan menunjuk instruksi atau menuliskannya bila perlu. Jika pekerjaan belum selesai, katakan statusnya dengan jelas alih-alih menjawab はい tanpa memahami. Laporkan kebutuhan bantuan dan hal yang telah dilakukan. Informasi sensitif hanya melalui saluran yang disetujui.',
       'Baca lokasi dan waktu|Periksa satuan|Ulangi angka penting|Laporkan fakta dan status', 'Jangan menyamakan ml dengan liter atau pukul pagi dengan sore.',
       'Jadwal tertulis 3階、午後2時、点検.', 'Konfirmasikan pemeriksaan di lantai tiga pukul dua siang.',
       '階~かい~lantai gedung|午前~ごぜん~sebelum tengah hari|午後~ごご~setelah tengah hari|完了~かんりょう~selesai',
       '三階のトイレで水漏れがあります。~さんがいのといれでみずもれがあります。~Ada kebocoran di toilet lantai tiga.|午後二時に点検します。~ごごにじにてんけんします。~Saya memeriksa pukul dua siang.',
       [('午後二時 berarti pukul berapa?', '14.00|02.00|12.00|20.00', '午後 menunjukkan setelah tengah hari; 二時 adalah pukul dua.'), ('三階のトイレで水漏れがあります melaporkan apa?', 'Kebocoran di toilet lantai tiga|Sampah di lobi|Kaca lantai dua retak|Stok sabun penuh', '三階 = lantai tiga, トイレ = toilet, 水漏れ = kebocoran air.')])
lesson('Kasus terpadu dan persiapan penilaian CBT',
       'Penilaian SSW pembersihan gedung mencakup pengetahuan dan keputusan praktik. Format resmi yang ditinjau adalah CBT teori 20 soal selama 20 menit dan penilaian praktik 30 soal selama 30 menit, masing-masing memerlukan 60 persen. Penilaian praktik dapat memakai foto, ilustrasi, benar-salah, pilihan, serta urutan. Simulasi aplikasi ini menggunakan soal pilihan dan skenario teks orisinal, sehingga tidak meniru seluruh variasi visual resmi.',
       'Saat membaca kasus, identifikasi bahaya paling mendesak, permukaan, jenis kotoran, alat, dan pengguna sebelum memilih metode. Jika data tidak cukup, konfirmasi lebih tepat daripada menebak. Urutan aman biasanya dimulai dengan pengendalian akses, persiapan sesuai instruksi, pembersihan, lalu pemeriksaan hasil. Tinjau pembahasan setelah latihan dan kembali ke lesson yang terkait. Nilai simulasi adalah indikator belajar, bukan bukti keterampilan lapangan atau hasil ujian resmi.',
       'Identifikasi bahaya utama|Cocokkan bahan dan metode|Pilih urutan aman|Tinjau hasil dan pelajari ulang', 'Keterampilan mesin dan akses tinggi tetap memerlukan praktik langsung serta supervisi.',
       'Lobi ramai, lantai peka air, dan ada tumpahan dekat kabel.', 'Amankan pengguna, hindari risiko listrik, koordinasikan penanganan, lalu gunakan metode sesuai material.',
       '学科~がっか~teori|実技~じつぎ~praktik|順番~じゅんばん~urutan|判断~はんだん~penilaian keputusan',
       '安全を先に確認します。~あんぜんをさきにかくにんします。~Saya memeriksa keselamatan terlebih dahulu.|分からない時は質問します。~わからないときはしつもんします。~Saya bertanya ketika tidak memahami.',
       [('Urutan aman untuk pekerjaan basah di jalur umum?', 'Amankan area, bersihkan, keringkan, periksa lalu buka|Pel lalu pasang rambu|Buka akses saat basah|Simpan alat di pintu darurat', 'Pengendalian akses dilakukan sebelum bahaya diciptakan dan diakhiri setelah inspeksi.'), ('Simulasi teks membuktikan kemampuan mengoperasikan mesin?', 'Tidak, diperlukan latihan langsung terawasi|Ya otomatis|Ya jika satu soal benar|Ya tanpa pelatihan', 'Pengambilan keputusan tertulis tidak menggantikan keterampilan praktik nyata.')])

sources = [dict(title='JBMA · SSW 1号: cakupan, CBT dan bahan belajar (ditinjau 17 Oktober 2026)', url='https://www.j-bma.or.jp/qualification-training/zairyu-1go'), dict(title='JBMA · Bidang pembersihan gedung', url='https://www.j-bma.or.jp/qualification-training/zairyu'), dict(title='MHLW · Keselamatan kerja dan informasi bahan kimia', url='https://anzeninfo.mhlw.go.jp/'), dict(title='CDC · Cleaning and disinfecting', url='https://www.cdc.gov/hygiene/about/when-and-how-to-clean-and-disinfect-your-home.html')]

